public boolean shouldPrintMessage(int timestamp, String message) {
    // Validate inputs
    if (timestamp < 0 || message == null) {
        return false;
    }
    // Retrieve the last printed timestamp for this message
    Integer last = lastPrinted.get(message);
    // If the message hasn't been printed before or it's been at least 10 seconds,
    // update the timestamp and allow printing.
    if (last == null || timestamp - last >= 10) {
        lastPrinted.put(message, timestamp);
        return true;
    }
    // Otherwise, suppress printing
    return false;
}

