private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Validate index
    if (i < 0 || i >= bb.limit()) {
        throw new IllegalArgumentException("Index out of bounds: " + i);
    }
    try {
        int b0 = bb.get(i) & 0xFF;
        int codePoint;
        int bytesConsumed;
        if (b0 <= 0x7F) {
            // 1-byte ASCII
            codePoint = b0;
            bytesConsumed = 1;
        } else if (b0 >= 0xC0 && b0 <= 0xDF) {
            // 2-byte sequence
            bytesConsumed = 2;
            if (i + 1 >= bb.limit()) {
                throw new IllegalArgumentException("Truncated UTF-8 sequence at index " + i);
            }
            int b1 = bb.get(i + 1) & 0xFF;
            if ((b1 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid continuation byte at index " + (i + 1));
            }
            codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
            if (codePoint < 0x80) {
                throw new IllegalArgumentException("Overlong encoding at index " + i);
            }
        } else if (b0 >= 0xE0 && b0 <= 0xEF) {
            // 3-byte sequence
            bytesConsumed = 3;
            if (i + 2 >= bb.limit()) {
                throw new IllegalArgumentException("Truncated UTF-8 sequence at index " + i);
            }
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid continuation byte at index " + (i + 1) + " or " + (i + 2));
            }
            codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
            if (codePoint < 0x800) {
                throw new IllegalArgumentException("Overlong encoding at index " + i);
            }
            if (codePoint >= 0xD800 && codePoint <= 0xDFFF) {
                throw new IllegalArgumentException("UTF-8 encoded surrogate half at index " + i);
            }
        } else if (b0 >= 0xF0 && b0 <= 0xF7) {
            // 4-byte sequence
            bytesConsumed = 4;
            if (i + 3 >= bb.limit()) {
                throw new IllegalArgumentException("Truncated UTF-8 sequence at index " + i);
            }
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            int b3 = bb.get(i + 3) & 0xFF;
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid continuation byte at index " + (i + 1) + ", " + (i + 2) + " or " + (i + 3));
            }
            codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            if (codePoint < 0x10000) {
                throw new IllegalArgumentException("Overlong encoding at index " + i);
            }
            if (codePoint > 0x10FFFF) {
                throw new IllegalArgumentException("Code point out of range at index " + i);
            }
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 leading byte at index " + i);
        }
        sb.append(Character.toChars(codePoint));
        return i + bytesConsumed;
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Index out of bounds while decoding UTF-8 at index " + i, e);
    }
}

