public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        // Attempt to use getFormattedMessage() if available
        try {
            java.lang.reflect.Method m = event.getClass().getMethod("getFormattedMessage");
            Object res = m.invoke(event);
            if (res instanceof String) {
                return (String) res;
            }
        } catch (NoSuchMethodException ignored) {
            // Method not present, ignore
        }

        // Attempt to use getRenderedMessage() if available
        try {
            java.lang.reflect.Method m = event.getClass().getMethod("getRenderedMessage");
            Object res = m.invoke(event);
            if (res instanceof String) {
                return (String) res;
            }
        } catch (NoSuchMethodException ignored) {
            // Method not present, ignore
        }

        // Fallback to getMessage()
        Object msg = event.getMessage();
        if (msg == null) {
            return "";
        }
        return msg.toString();
    } catch (Exception e) {
        // In case of any unexpected exception, return an empty string
        return "";
    }
}

