@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph must not be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map must not be null");
    }
    try {
        // Create left partition vertices A1, A2, A3
        java.util.List<V> left = new java.util.ArrayList<>();
        for (int i = 1; i <= 3; i++) {
            String name = "A" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) name;
            target.addVertex(vertex);
            resultMap.put(name, vertex);
            left.add(vertex);
        }
        // Create right partition vertices B1, B2, B3
        java.util.List<V> right = new java.util.ArrayList<>();
        for (int i = 1; i <= 3; i++) {
            String name = "B" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) name;
            target.addVertex(vertex);
            resultMap.put(name, vertex);
            right.add(vertex);
        }
        // Add all edges between left and right partitions
        for (V u : left) {
            for (V v : right) {
                target.addEdge(u, v);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

protected int findByte(byte value, int pos) {
    // Ensure the buffer exists
    if (buffer == null) {
        return -1;
    }
    // Validate starting position
    if (pos < 0 || pos >= buffer.length) {
        return -1;
    }
    // Search for the byte starting from pos
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }
    // Not found
    return -1;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    int size = schema.getSerializedSize(message, buffer);
    if (size < 0) {
        throw new IllegalStateException("Negative size computed for message");
    }
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    schema.writeTo(message, cos);
    cos.flush();
    return size;
}

