@Override
public void accept(final METRICS data) {
    if (data == null) {
        throw new IllegalArgumentException("data cannot be null");
    }
    try {
        // Assume a cache map exists in the enclosing class
        Object key = extractKey(data);
        METRICS existing = cache.get(key);
        if (existing == null) {
            cache.put(key, data);
        } else {
            // Attempt to merge if the METRICS type provides a merge method
            try {
                java.lang.reflect.Method mergeMethod = data.getClass().getMethod("merge", data.getClass());
                mergeMethod.invoke(existing, data);
            } catch (NoSuchMethodException ignored) {
                // Fallback: replace the existing value
                cache.put(key, data);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to accept data", e);
    }
}

private Object extractKey(METRICS data) {
    try {
        java.lang.reflect.Method getKey = data.getClass().getMethod("getKey");
        return getKey.invoke(data);
    } catch (Exception e) {
        // If no getKey method, use the data object itself as key
        return data;
    }
}

