public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    if (clients == null) {
        return;
    }
    String outMsg = message + "\r\n";
    java.util.Iterator<java.net.Socket> it = clients.iterator();
    while (it.hasNext()) {
        java.net.Socket client = it.next();
        if (client == null) {
            it.remove();
            continue;
        }
        try {
            java.io.OutputStream out = client.getOutputStream();
            if (out == null) {
                it.remove();
                continue;
            }
            out.write(outMsg.getBytes());
            out.flush();
        } catch (java.io.IOException e) {
            try {
                client.close();
            } catch (java.io.IOException ex) {
                // ignore
            }
            it.remove();
        }
    }
}

