public void put(LoggingEvent o){
    if (o == null) {
        return;
    }
    synchronized (this) {
        // If the buffer array is not initialized, silently drop the event
        if (buffer == null) {
            return;
        }
        // If the buffer is full, silently drop the event
        if (count == buffer.length) {
            return;
        }
        // Place the event into the buffer at the current tail position
        buffer[tail] = o;
        // Advance the tail index in a circular fashion
        tail = (tail + 1) % buffer.length;
        // Increment the count of stored events
        count++;
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input parameters
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }
    // If the range is empty, return an empty list
    if (start == end) {
        return new ArrayList<>();
    }

    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;

    while (currentStart < end) {
        long next;
        // Safely compute the next end point without overflow
        if (currentStart > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            next = end;
        } else {
            next = currentStart + FETCH_DATA_DURATION;
            if (next > end) {
                next = end;
            }
        }
        ranges.add(new TimeRange(currentStart, next));
        currentStart = next;
    }

    return ranges;
}

