static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    // Validate timeBucket
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be a positive long in YYYYMMDD format");
    }
    // Extract year, month, day
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);
    // Basic range checks
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }
    // Validate actual date using java.time.LocalDate
    try {
        java.time.LocalDate.of(year, month, day);
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("timeBucket does not represent a valid date: " + timeBucket, e);
    }
    // Compute bucket start day
    int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
    // Reconstruct compressed date
    return (long) year * 10000 + (long) month * 100 + bucketStartDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String must not be null");
    }
    if (index < 0 || len < 0 || index > str.length() || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; ) {
        int cp = Character.codePointAt(str, i, end);
        int bytes;
        if (cp <= 0x7F) {
            bytes = 1;
        } else if (cp <= 0x7FF) {
            bytes = 2;
        } else if (cp <= 0xFFFF) {
            bytes = 3;
        } else {
            bytes = 4;
        }
        size += bytes;
        i += Character.charCount(cp);
    }
    return size;
}

