public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("key and props must not be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String varName = matcher.group(1);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            varValue = matcher.group(0); // leave placeholder unchanged
        }
        matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(varValue));
    }
    matcher.appendTail(sb);
    String result = sb.toString();
    int maxDepth = 10;
    int depth = 0;
    while (depth < maxDepth) {
        matcher = pattern.matcher(result);
        if (!matcher.find()) {
            break;
        }
        sb = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
                varValue = matcher.group(0);
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(varValue));
        }
        matcher.appendTail(sb);
        result = sb.toString();
        depth++;
    }
    return result;
}

