private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Both null => true
    if (str == null && suffix == null) {
        return true;
    }
    // One null => false
    if (str == null || suffix == null) {
        return false;
    }
    // Empty suffix always matches
    if (suffix.isEmpty()) {
        return true;
    }
    // String shorter than suffix cannot match
    if (str.length() < suffix.length()) {
        return false;
    }
    // Use regionMatches for efficient case handling
    return str.regionMatches(ignoreCase, str.length() - suffix.length(), suffix, 0, suffix.length());
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }
    // Remove leading slash if present (absolute path)
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // If path is now empty, return empty list
    if (path.isEmpty()) {
        return new ArrayList<>();
    }
    String[] parts = path.split("/", -1); // keep trailing empty segments
    List<PathSegmentImpl> segments = new ArrayList<>(parts.length);
    for (String part : parts) {
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("Invalid percent-encoding in path segment: " + part, e);
            }
        }
        // Create PathSegmentImpl; use two-arg constructor if available, otherwise one-arg
        try {
            segments.add(new PathSegmentImpl(value, null));
        } catch (NoSuchMethodError | IllegalArgumentException e) {
            // Fallback to one-arg constructor
            segments.add(new PathSegmentImpl(value));
        }
    }
    return segments;
}

