public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    // Retrieve the bounds of the original box
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();

    // Validate the box coordinates
    if (minX > maxX || minY > maxY) {
        throw new IllegalArgumentException("Invalid box coordinates");
    }

    // Compute the midpoint along the X axis
    double midX = (minX + maxX) / 2.0;

    // Create the two new boxes
    Box2D leftBox  = new Box2D(minX, minY, midX, maxY);
    Box2D rightBox = new Box2D(midX, minY, maxX, maxY);

    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    if (data == null) {
        int newCap = size;
        if (newCap < 0) {
            newCap = Integer.MAX_VALUE;
        }
        data = new byte[newCap];
        return;
    }
    if (size > Integer.MAX_VALUE - length) {
        throw new IllegalArgumentException("Requested size too large");
    }
    int currentCap = data.length;
    int freeSpace = currentCap - length;
    if (freeSpace >= size) {
        return;
    }
    long newCapLong = Math.max((long) currentCap * 2, (long) currentCap + size);
    if (newCapLong > Integer.MAX_VALUE) {
        newCapLong = Integer.MAX_VALUE;
    }
    int newCap = (int) newCapLong;
    if (newCap <= currentCap) {
        newCap = currentCap + size;
    }
    byte[] newData = new byte[newCap];
    System.arraycopy(data, 0, newData, 0, length);
    data = newData;
}

