@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }
    // Null values are allowed and simply return null
    if (value == null) {
        return null;
    }
    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }
    // String conversion: must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0); // autoboxes to Character
        } else {
            throw new Exception("Cannot convert String of length " + str.length() + " to Character");
        }
    }
    // Number conversion: cast to char if within valid range
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < 0 || intVal > 0xFFFF) {
            throw new Exception("Number value out of char range: " + intVal);
        }
        return (char) intVal; // autoboxes to Character
    }
    // Unsupported type
    throw new Exception("Cannot convert type " + value.getClass().getName() + " to java.lang.Character");
}

