public static int nextPrime(int desiredCapacity) {
    // Handle non-positive or very small capacities
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity == 3) {
        return 3;
    }
    // If desiredCapacity is close to Integer.MAX_VALUE, return Integer.MAX_VALUE
    if (desiredCapacity >= Integer.MAX_VALUE - 1) {
        return Integer.MAX_VALUE;
    }

    // Start searching from the next odd number >= desiredCapacity
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }

    // Compute the upper bound for the 11% rule
    long limit = (long) Math.floor(desiredCapacity * 1.11);
    if (limit > Integer.MAX_VALUE) {
        limit = Integer.MAX_VALUE;
    }

    // Search within the 11% range first
    for (long n = candidate; n <= limit; n += 2) {
        if (isPrime((int) n)) {
            return (int) n;
        }
    }

    // If no prime found within the range, continue searching beyond it
    for (long n = limit + 1; n <= Integer.MAX_VALUE; n += 2) {
        if (isPrime((int) n)) {
            return (int) n;
        }
    }

    // Fallback: return Integer.MAX_VALUE if no prime was found (unlikely)
    return Integer.MAX_VALUE;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

