public static Object findFirstMatch(Collection source, Collection candidates) {
    // Handle null inputs gracefully
    if (source == null || candidates == null) {
        return null;
    }

    // Iterate over candidates in their natural order
    for (Object candidate : candidates) {
        try {
            if (source.contains(candidate)) {
                return candidate;
            }
        } catch (NullPointerException | ClassCastException | IllegalArgumentException e) {
            // These exceptions can occur if the source collection does not support
            // the candidate element (e.g., null or incompatible type). Skip to next.
            continue;
        } catch (RuntimeException e) {
            // For any other runtime exception, rethrow to avoid masking bugs
            throw e;
        }
    }

    // No match found
    return null;
}

