    // Ensure the underlying input stream is available
    if (in == null) {
        throw new IOException("Input stream is null");
    }

    // Read the length prefix (assumed to be a 4‑byte integer)
    int length;
    try {
        length = in.readInt();
    } catch (EOFException e) {
        throw new IOException("Unexpected end of stream while reading string length", e);
    }

    // Validate the length
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    if (length == 0) {
        return "";
    }

    // Allocate buffer for the string bytes
    byte[] bytes;
    try {
        bytes = new byte[length];
    } catch (OutOfMemoryError e) {
        throw new IOException("String length too large: " + length, e);
    }

    // Read the string bytes
    try {
        in.readFully(bytes);
    } catch (EOFException e) {
        throw new IOException("Unexpected end of stream while reading string data", e);
    }

    // Convert bytes to a UTF‑8 string
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

