public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            i++;
            continue;
        }
        // Handle escape sequence
        if (i + 1 >= len) {
            // Trailing backslash, treat as literal
            sb.append('\\');
            i++;
            continue;
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case '\\':
                sb.append('\\');
                i += 2;
                break;
            case 'b':
                sb.append('\b');
                i += 2;
                break;
            case 't':
                sb.append('\t');
                i += 2;
                break;
            case 'n':
                sb.append('\n');
                i += 2;
                break;
            case 'f':
                sb.append('\f');
                i += 2;
                break;
            case 'r':
                sb.append('\r');
                i += 2;
                break;
            case '\'':
                sb.append('\'');
                i += 2;
                break;
            case '\"':
                sb.append('\"');
                i += 2;
                break;
            case 'u':
                // Unicode escape: \uXXXX
                if (i + 6 > len) {
                    throw new Exception("Invalid Unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid Unicode escape sequence: \\u" + hex, e);
                }
                i += 6;
                break;
            default:
                // Check for octal escape (up to 3 digits 0-7)
                if (next >= '0' && next <= '7') {
                    int j = i + 1;
                    int end = j;
                    while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                        end++;
                    }
                    String oct = str.substring(j, end);
                    try {
                        int code = Integer.parseInt(oct, 8);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid octal escape sequence: \\" + oct, e);
                    }
                    i = end;
                } else {
                    // Unknown escape, keep the character as is
                    sb.append(next);
                    i += 2;
                }
                break;
        }
    }
    return sb.toString();
}

