final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    if (classFileBuffer == null) {
        throw new IllegalStateException("classFileBuffer is null");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    if (classFileBuffer.length < 10) {
        throw new IllegalArgumentException("classFileBuffer too short to contain constant pool");
    }
    // constant_pool_count is at offset 8-9
    int cpCount = ((classFileBuffer[8] & 0xFF) << 8) | (classFileBuffer[9] & 0xFF);
    if (constantPoolEntryIndex >= cpCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }
    int offset = 10;
    try {
        for (int i = 1; i < constantPoolEntryIndex; i++) {
            int tag = classFileBuffer[offset] & 0xFF;
            offset++;
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                    offset += 2 + len;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                    offset += 4;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 8;
                    i++; // these take up two entries
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                    offset += 2;
                    break;
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                    offset += 4;
                    break;
                case 12: // CONSTANT_NameAndType
                    offset += 4;
                    break;
                case 15: // CONSTANT_MethodHandle
                    offset += 3;
                    break;
                case 16: // CONSTANT_MethodType
                    offset += 2;
                    break;
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
            }
        }
        // Now at the target entry
        int tag = classFileBuffer[offset] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Constant pool entry is not a CONSTANT_Utf8");
        }
        offset++;
        int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
        offset += 2;
        if (length > charBuffer.length) {
            throw new IllegalArgumentException("charBuffer too small for UTF-8 string");
        }
        if (offset + length > classFileBuffer.length) {
            throw new IllegalArgumentException("classFileBuffer does not contain enough bytes for the UTF-8 string");
        }
        java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
        java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer, offset, length);
        java.nio.CharBuffer charBuf = java.nio.CharBuffer.wrap(charBuffer);
        decoder.reset();
        decoder.decode(byteBuf, charBuf, true);
        decoder.flush(charBuf);
        int decodedLength = charBuf.position();
        return new String(charBuffer, 0, decodedLength);
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Malformed constant pool entry", e);
    } catch (java.nio.charset.CharacterCodingException e) {
        throw new IllegalArgumentException("Failed to decode UTF-8 string", e);
    }
}

