private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    if (dir == 0) {
        throw new IllegalArgumentException("Direction must be non‑zero");
    }
    try {
        // If the start and stop are the same, simply return a circulator to it.
        if (start.equals(stop)) {
            return new OuterFaceCirculator(stop);
        }

        OuterFaceCirculator circ = new OuterFaceCirculator(start);
        while (true) {
            Node current = circ.getNode();
            if (current == null) {
                throw new IllegalStateException("Circulator returned a null node");
            }

            // Stop if we reached the stop node.
            if (current.equals(stop)) {
                return circ;
            }

            // Return if the predicate matches.
            if (predicate.test(current)) {
                return circ;
            }

            // Advance in the requested direction.
            circ = dir > 0 ? circ.next() : circ.prev();

            // Safety check: if we loop back to the start without finding the stop,
            // return a circulator positioned at the stop node.
            if (circ.getNode().equals(start)) {
                return new OuterFaceCirculator(stop);
            }
        }
    } catch (Exception e) {
        throw new IllegalStateException("Failed to select node on outer face", e);
    }
}

