public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    if (byteLength <= 0) {
        return this;
    }
    if (byteOffset < 0) {
        throw new IllegalArgumentException("byteOffset must be non-negative");
    }
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    int newLen = length + byteLength;
    if (data == null) {
        int cap = Math.max(16, newLen);
        data = new byte[cap];
    } else if (newLen > data.length) {
        int newCap = Math.max(data.length * 2, newLen);
        byte[] newData = new byte[newCap];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
    if (byteArrayValue == null) {
        for (int i = length; i < newLen; i++) {
            data[i] = 0;
        }
    } else {
        if (byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
        }
        System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
    }
    length = newLen;
    return this;
}

