    int result = 1;
    java.lang.reflect.Field[] fields = this.getClass().getDeclaredFields();
    for (java.lang.reflect.Field field : fields) {
        if (java.lang.reflect.Modifier.isStatic(field.getModifiers())) {
            continue;
        }
        field.setAccessible(true);
        try {
            Object value = field.get(this);
            result = 31 * result + (value == null ? 0 : value.hashCode());
        } catch (IllegalAccessException e) {
            // If we cannot access the field, ignore it for hash calculation
        }
    }
    return result;
}

public static String deleteAny(String inString, String charsToDelete) {
    // Handle null inputs
    if (inString == null) {
        return null;
    }
    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }

    // Use a boolean array for quick lookup of characters to delete
    // Supports all Unicode code points up to 65535
    boolean[] deleteMap = new boolean[65536];
    for (int i = 0; i < charsToDelete.length(); i++) {
        deleteMap[charsToDelete.charAt(i)] = true;
    }

    StringBuilder result = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char c = inString.charAt(i);
        if (!deleteMap[c]) {
            result.append(c);
        }
    }
    return result.toString();
}

public final MatchResult match(CharSequence uri){
    if (uri == null) {
        return null;
    }
    try {
