        java.util.regex.Pattern p = this.pattern;
        if (p == null) {
            return null;
        }
        java.util.regex.Matcher m = p.matcher(uri);
        if (!m.matches()) {
            return null;
        }
        // Assume the class has a java.util.List<String> field named 'variableNames'
        java.util.List<String> names = this.variableNames;
        java.util.Map<String, String> vars = new java.util.HashMap<>();
        int groupCount = m.groupCount();
        if (names == null || names.size() != groupCount) {
            // Fallback: use generic variable names
            for (int i = 1; i <= groupCount; i++) {
                vars.put("var" + i, m.group(i));
            }
        } else {
            for (int i = 1; i <= groupCount; i++) {
                String name = names.get(i - 1);
                vars.put(name, m.group(i));
            }
        }
        // Assume MatchResult has a constructor that accepts a Map<String, String>
        return new MatchResult(vars);
    } catch (Exception e) {
        // In case of any unexpected error, return null to indicate no match
        return null;
    }
}

public static byte convertHexDigit(byte b){
    int c = b & 0xFF; // treat byte as unsigned
    if (c >= '0' && c <= '9') {
        return (byte)(c - '0');
    } else if (c >= 'a' && c <= 'f') {
        return (byte)(c - 'a' + 10);
    } else if (c >= 'A' && c <= 'F') {
        return (byte)(c - 'A' + 10);
    } else {
        throw new IllegalArgumentException("Invalid hex digit: " + (char)c);
    }
}

