private void check(String modelName) throws IllegalStateException {
    java.util.List<Integer> indices = shardingKeyIndices;
    if (indices == null || indices.isEmpty()) {
        return;
    }
    java.util.List<Integer> sorted = new java.util.ArrayList<>(indices);
    java.util.Collections.sort(sorted);
    Integer start = sorted.get(0);
    if (start == null) {
        throw new IllegalStateException("Sharding key indices contain null for model " + modelName);
    }
    for (int i = 0; i < sorted.size(); i++) {
        Integer val = sorted.get(i);
        if (val == null) {
            throw new IllegalStateException("Sharding key indices contain null for model " + modelName);
        }
        if (val - start != i) {
            throw new IllegalStateException("Sharding key indices are not continuous for model " + modelName);
        }
    }
}

public byte readByte() throws IOException {
    if (buffer == null) {
        throw new IOException("Buffer not initialized");
    }
    if (buffer.length == 0) {
        throw new IOException("Buffer size is zero");
    }
    while (pos >= limit) {
        int read = in.read(buffer);
        if (read == -1) {
            throw new IOException("End of stream");
        }
        if (read == 0) {
            // If the underlying stream returned 0 bytes, try again
            continue;
        }
        pos = 0;
        limit = read;
    }
    return buffer[pos++];
}

