public int compare(Object aObj1, Object aObj2) {
    // Handle reference equality first
    if (aObj1 == aObj2) {
        return 0;
    }
    // Null handling: null is considered less than any non-null object
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // If the first object implements Comparable, attempt to compare
    if (aObj1 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> comp = (Comparable<Object>) aObj1;
            return comp.compareTo(aObj2);
        } catch (ClassCastException e) {
            // The objects are not mutually comparable
            throw new ClassCastException(
                "Objects are not mutually comparable: " + aObj1 + " and " + aObj2);
        } catch (Exception e) {
            // Any other exception during comparison
            throw new RuntimeException(
                "Comparison failed for objects: " + aObj1 + " and " + aObj2, e);
        }
    } else {
        // The first object does not implement Comparable
        throw new ClassCastException(
            "First object does not implement Comparable: " + aObj1);
    }
}

public int appendLoopOnAppenders(LoggingEvent event) {
