    java.util.List<org.apache.log4j.Appender> appenderList = this.appenders;
    if (appenderList == null) {
        return 0;
    }
    for (org.apache.log4j.Appender appender : appenderList) {
        if (appender == null) {
            continue;
        }
        try {
            appender.doAppend(event);
            count++;
        } catch (Throwable t) {
            // Exception from an appender should not stop the loop
            // Optionally log the exception here
        }
    }
    return count;
}

