int addConstantNameAndType(final String name,final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    try {
        // Ensure the constant pool list exists
        if (constantPool == null) {
            constantPool = new ArrayList<>();
        }
        // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor
        for (int i = 0; i < constantPool.size(); i++) {
            ConstantPoolInfo entry = constantPool.get(i);
            if (entry.getTag() == 12) { // CONSTANT_NameAndType
                int nameIdx = entry.getNameIndex();
                int descIdx = entry.getDescriptorIndex();
                String existingName = getUtf8String(nameIdx);
                String existingDesc = getUtf8String(descIdx);
                if (name.equals(existingName) && descriptor.equals(existingDesc)) {
                    return i; // Return the index of the existing entry
                }
            }
        }
        // Add UTF8 entries for the name and descriptor
        int nameIdx = addConstantUtf8(name);
        int descIdx = addConstantUtf8(descriptor);
        // Create and add the new NameAndType entry
        ConstantPoolInfo newEntry = new ConstantPoolInfo(12, nameIdx, descIdx);
        constantPool.add(newEntry);
        return constantPool.size() - 1; // Return the index of the new entry
    } catch (Exception e) {
        throw new RuntimeException("Failed to add CONSTANT_NameAndType to constant pool", e);
    }
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // If both arrays are null, return null
    if (array1 == null && array2 == null) {
        return null;
    }
    // If one of the arrays is null, return a copy of the other
    if (array1 == null) {
        // Return a new array containing all elements of array2
        String[] result = new String[array2.length];
        System.arraycopy(array2, 0, result, 0, array2.length);
        return result;
    }
    if (array2 == null) {
        // Return a new array containing all elements of array1
        String[] result = new String[array1.length];
        System.arraycopy(array1, 0, result, 0, array1.length);
        return result;
    }
    // Both arrays are non-null; concatenate them
    int len1 = array1.length;
    int len2 = array2.length;
    String[] result = new String[len1 + len2];
    System.arraycopy(array1, 0, result, 0, len1);
    System.arraycopy(array2, 0, result, len1, len2);
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate input
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }

    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }

    // If the source bucket is already bucket 0, nothing to move
    if (minLabel == 0) {
        return;
    }

    // Ensure bucket 0 exists
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<Integer>();
        bucketsByLabel.set(0, target);
    }

    // Move vertices from source to target and update labels
    for (Integer v : source) {
        if (v == null) {
            continue;
        }
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
        target.add(v);
    }

    // Clear the source bucket
    source.clear();
}

