            // This bucket is the head of the list; update the hash table's head reference.
            this.hashTable.head = this.next;
        }
        // If this bucket has a next bucket, link it back to this bucket's previous.
        if (this.next != null) {
            this.next.prev = this.prev;
        }
        // Null out references to help GC and avoid accidental use.
        this.prev = null;
        this.next = null;
        this.hashTable = null;
    } catch (Exception e) {
