private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null or empty input
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long totalSum = 0L;

    // Compute suffix sums from the end
    for (int i = n - 1; i >= 0; i--) {
        totalSum += bounds.get(i);
        // Cast to int; if overflow occurs, it will wrap around as per Java's integer overflow rules
        suffix.add(0, (int) totalSum);
    }

    return new Pair<>(suffix, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array is null");
    }
    int len = arr.length;
    if (from < 0 || to >= len) {
        throw new IndexOutOfBoundsException(
            "Index out of bounds: from=" + from + ", to=" + to + ", length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException(
            "from index greater than to index: from=" + from + ", to=" + to);
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

