        throw new IllegalArgumentException("Source list cannot be null");
    }
    // No-op if the source is this list or empty
    if (list == this || list.size == 0) {
        return;
    }

    // If this list is empty, simply adopt the source nodes
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
        this.size = list.size;
    } else {
        // Both lists are non-empty: splice the source list after this list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
        this.size += list.size;
    }

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && prefix == null) {
        return true;
    }
    // If only one is null, no match
    if (str == null || prefix == null) {
        return false;
    }
    // If prefix is longer than the string, it cannot match
    if (prefix.length() > str.length()) {
        return false;
    }
    // Perform the comparison, optionally ignoring case
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

