public void putAllWriteable(BeanMap map){
    if (map == null) {
        throw new IllegalArgumentException("map cannot be null");
    }
    Object sourceBean = map.getBean();
    if (sourceBean == null) {
        return;
    }
    java.util.Map<String, java.beans.PropertyDescriptor> sourcePdMap = new java.util.HashMap<>();
    try {
        java.beans.PropertyDescriptor[] pds = java.beans.Introspector.getBeanInfo(sourceBean.getClass(), Object.class).getPropertyDescriptors();
        for (java.beans.PropertyDescriptor pd : pds) {
            sourcePdMap.put(pd.getName(), pd);
        }
    } catch (java.beans.IntrospectionException e) {
        // Unable to introspect source bean; nothing to copy
        return;
    }
    for (Object keyObj : map.keySet()) {
        if (!(keyObj instanceof String)) {
            continue;
        }
        String key = (String) keyObj;
        java.beans.PropertyDescriptor pd = sourcePdMap.get(key);
        if (pd == null) {
            continue;
        }
        if (pd.getReadMethod() == null || pd.getWriteMethod() == null) {
            continue; // ignore read‑only or write‑only properties
        }
        Object value = map.get(key);
        try {
            this.put(key, value);
        } catch (IllegalArgumentException e) {
            // ignore properties that cannot be written to this BeanMap
        }
    }
}

