public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    if (row < 0 || row >= table.getRowCount()) {
        return;
    }
    // Ensure the table is actually the view of the provided JScrollPane
    if (pane.getViewport().getView() != table) {
        return;
    }
    try {
        // Select the specified row
        table.setRowSelectionInterval(row, row);
        // Scroll the table so that the selected row becomes visible
        java.awt.Rectangle rect = table.getCellRect(row, 0, true);
        if (rect != null) {
            table.scrollRectToVisible(rect);
        }
        // Delay repaint to allow the table to paint the newly selected row
        javax.swing.SwingUtilities.invokeLater(() -> {
            javax.swing.SwingUtilities.invokeLater(() -> table.repaint());
        });
    } catch (Exception e) {
        // Silently ignore any unexpected exceptions
    }
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // If count is zero, nothing to compare – always true
    if (count == 0) {
        return true;
    }
    // Negative count is invalid
    if (count < 0) {
        return false;
    }
    // Null arrays cannot be compared for non‑zero count
    if (a == null || b == null) {
        return false;
    }
    // Ensure we don't read past the end of either array
    if (count > a.length || count > b.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart >= buf.length()) {
        // Nothing to abbreviate
        return;
    }
    // Find the end of the name (next space or end of buffer)
    int end = buf.indexOf(" ", nameStart);
    if (end == -1) {
        end = buf.length();
    }
    String name = buf.substring(nameStart, end).trim();
    if (name.isEmpty()) {
        return;
    }
    // Split the name into parts and build abbreviation
    String[] parts = name.split("\\s+");
    StringBuilder abbr = new StringBuilder();
    for (String part : parts) {
        if (!part.isEmpty()) {
            abbr.append(part.charAt(0)).append('.');
        }
    }
    if (abbr.length() == 0) {
        return;
    }
    // Append abbreviation to the buffer, ensuring a space separator if needed
    if (buf.length() > 0 && buf.charAt(buf.length() - 1) != ' ') {
        buf.append(' ');
    }
    buf.append(abbr);
}

