private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // empty or single vertex is trivially a clique
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V vi = (V) arr[i];
        for (int j = i + 1; j < size; j++) {
            V vj = (V) arr[j];
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    // Handle null or empty input
    if (keys == null || keys.isEmpty()) {
        return new ArrayList<>();
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    // Iterate over each key to find its maximum lower bound
    for (K key : keys) {
        // If the key is null, we cannot compute a lower bound
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        // Ensure the key is an Integer; otherwise, throw an exception
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("Key is not an Integer: " + key);
        }
        int current = (Integer) key;
        int maxLower = Integer.MIN_VALUE;
        boolean found = false;
        // Scan all keys to find the maximum value strictly less than current
        for (K other : keys) {
            if (other == null || other == key) {
                continue;
            }
            if (!(other instanceof Integer)) {
                throw new IllegalArgumentException("Key is not an Integer: " + other);
            }
            int val = (Integer) other;
            if (val < current && val > maxLower) {
                maxLower = val;
                found = true;
            }
        }
        // Add the found lower bound or null if none exists
        lowerBounds.add(found ? maxLower : null);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new NullPointerException("descriptor");
    }
    if (descriptor.length() == 0) {
        throw new IllegalArgumentException("Empty descriptor");
    }
    if (descriptor.charAt(0) == '(') {
        int i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            i = popDescriptor(descriptor, i);
        }
        if (i >= descriptor.length() || descriptor.charAt(i) != ')') {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
    } else {
        popDescriptor(descriptor, 0);
    }
}

private int popDescriptor(final String descriptor, int i) {
    char c = descriptor.charAt(i);
    if (c == '[') {
        while (i < descriptor.length() && descriptor.charAt(i) == '[') {
            i++;
        }
        i = popDescriptor(descriptor, i);
    } else if (c == 'L') {
        int semicolon = descriptor.indexOf(';', i);
        if (semicolon == -1) {
            throw new IllegalArgumentException("Invalid object type descriptor");
        }
        i = semicolon + 1;
    } else {
        // Primitive type: single char
        i++;
    }
    if (outputFrameStackSize <= 0) {
        throw new IllegalStateException("Stack underflow");
    }
    outputFrameStack[--outputFrameStackSize] = null;
    return i;
}

