public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSeparator = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    return lastDot > lastSeparator ? lastDot : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            // Non-positive threshold means the metric should be considered expired immediately.
            return true;
        }
        long currentTime = System.currentTimeMillis();
        // If the timestamp is in the future relative to current time, it cannot be expired.
        if (timestamp > currentTime) {
            return false;
        }
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, conservatively consider the metric expired.
        return true;
    }
}

Edge edgeToNext() {
    // Ensure that we have both a current and a next node to connect.
    if (current == null || next == null) {
