}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen - subLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getRenderedMessage();
    if (message == null) {
        return;
    }
    // Append a line separator to ensure each log entry is on its own line
    message += System.lineSeparator();
    // If there are no connected clients, nothing to do
    if (clients == null) {
        return;
    }
    // Iterate over the clients safely
    synchronized (clients) {
        java.util.Iterator<java.net.Socket> it = clients.iterator();
        while (it.hasNext()) {
            java.net.Socket client = it.next();
            if (client == null) {
                continue;
            }
            try {
                java.io.OutputStream out = client.getOutputStream();
                out.write(message.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                out.flush();
            } catch (java.io.IOException e) {
                // If an error occurs, remove the client from the list and close the socket
                it.remove();
                try {
                    client.close();
                } catch (java.io.IOException ex) {
                    // Ignore secondary exception
                }
            }
        }
    }
}

