    return String.valueOf(ch);
}

private void checkIfPackedField() throws IOException {
    // Ensure the input stream is available
    if (input == null) {
        throw new IOException("Input stream is null");
    }

    // Determine the wire type from the current tag
    int wireType = tag & 0x7;
    if (wireType == 2) { // Length-delimited field, could be packed
        packed = true;
        packedFieldNumber = tag >>> 3;

        // Read the length of the packed data
        int length = input.readRawVarint32();
        if (length < 0) {
            throw new IOException("Negative length for packed field");
        }

        // Set a limit on the input to read only the packed data
        packedFieldLimit = input.pushLimit(length);
    } else {
        // Not a packed field
        packed = false;
        packedFieldNumber = 0;
        packedFieldLimit = 0;
    }
}

public int readTag() throws IOException {
    try {
        return readRawVarint32();
    } catch (EOFException e) {
        // Reached end of input; signal end of message by returning 0
        return 0;
    }
}

