    sb.append("/");
    sb.append(total > 0 ? total : "*");
    return sb.toString();
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a file: " + file);
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges cannot be null");
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    java.util.List<String> lines = java.nio.file.Files.readAllLines(file.toPath(), java.nio.charset.StandardCharsets.UTF_8);
    for (String line : lines) {
        if (line == null || line.trim().isEmpty()) {
            continue;
        }
        ThreadSnapshot snapshot;
        try {
            snapshot = new ThreadSnapshot(line);
        } catch (Exception e) {
            // Skip lines that cannot be parsed into a ThreadSnapshot
            continue;
        }
        long ts;
        try {
            ts = snapshot.getTimestamp();
        } catch (Exception e) {
            // Skip snapshots without a valid timestamp
            continue;
        }
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) {
                continue;
            }
            long start = range.getStartTime();
            long end = range.getEndTime();
            if (ts >= start && ts <= end) {
                result.add(snapshot);
                break;
            }
        }
    }
    return result;
}
